// Logical reads over P7A's bounded storage. Exact tags prevent a recycled slot
// from being interpreted as an older level or day.
import { eventFacts } from './facts.js';
import { loadSchema } from './schema.js';
import { previousEvents } from './event-store.js';
import { checkAbort } from './client.js';

const MASK24 = 0xffffffn;
const MASK232 = (1n << 232n) - 1n;
const CUSTOM = 1n << 40n;

export async function generationStart(s, level, signal) {
  checkAbort(signal);
  const schema = await loadSchema('GAME');
  checkAbort(signal);
  if (schema.fields.ticketGenerationStartBlock.type.startsWith('mapping:')) {
    return s.field('GAME', 'ticketGenerationStartBlock', level);
  }
  const stamp = BigInt(await s.field('GAME', 'ticketGenerationStartBlock'));
  checkAbort(signal);
  if ((stamp & MASK24) === BigInt(level)) return stamp >> 24n;
  if (!stamp || BigInt(level) > (stamp & MASK24)) return 0n;
  // The latest stamped generation bounds every older level. Seek backward
  // from that block instead of scanning the entire deployment on a cold visit.
  const rows = await previousEvents(s.client, 'GAME', 'TicketGenerationStarted', {
    blockNumber: Number(stamp >> 24n),
    transactionIndex: Number.MAX_SAFE_INTEGER,
    logIndex: Number.MAX_SAFE_INTEGER,
  }, { filters: { level }, signal });
  return BigInt(rows[0]?.args.blockNumber ?? 0);
}

export async function foilDrawFor(s, day, signal) {
  checkAbort(signal);
  const schema = await loadSchema('GAME');
  checkAbort(signal);
  if (schema.fields.dailyFoilDraw.type.startsWith('mapping:')) return s.field('GAME', 'dailyFoilDraw', day);
  const value = BigInt(await s.field('GAME', 'dailyFoilDraw', Number(day) & 1));
  checkAbort(signal);
  if (((value >> 217n) & MASK24) === BigInt(day)) return value;
  const rows = await eventFacts(s, ['DailyWinningTraits'], { contract: 'GAME', filters: { day }, signal });
  if (!rows.length) return 0n;
  const at = await s.client.snapshot({ blockTag: rows.at(-1).blockNumber, signal });
  const historical = BigInt(await at.field('GAME', 'dailyFoilDraw', Number(day) & 1));
  return ((historical >> 217n) & MASK24) === BigInt(day) ? historical : 0n;
}

export async function crapsField(s, label, slot) {
  const schema = await loadSchema('CRAPS');
  if (!schema.fields._battleDays) return s.field('CRAPS', label, slot);
  const logical = BigInt(slot), day = logical >> 3n;
  const custom = logical >= CUSTOM;
  if (label === '_dayTickets') {
    const value = BigInt(await s.field('CRAPS', label, day & 63n));
    return value >> 232n === day ? value & MASK232 : 0n;
  }
  const physical = custom ? logical : logical & 511n;
  if (label === '_jackpotRounds') {
    const value = await s.field('CRAPS', label, physical);
    if (BigInt(value.day) === day && value.requestDay) return {
      ...value,
      word: value.drawWord == null ? value.word : (BigInt(value.drawCursor) & (1n << 207n) ? value.drawWord : 0n),
      bankroll: value.started === false ? 0n : value.bankroll,
    };
    return Object.fromEntries(Object.keys(value).map(key => [key, typeof value[key] === 'boolean' ? false : 0n]));
  }
  const key = ['_battles', '_highField'].includes(label) ? '0x' + physical.toString(16).padStart(64, '0') : physical;
  const value = BigInt(await s.field('CRAPS', label, key));
  if (custom) return value;
  if (label === '_battles') {
    const tags = BigInt(await s.field('CRAPS', '_battleDays', day & 63n));
    return tags >> 232n === day && (tags & (1n << (logical & 7n))) ? value : 0n;
  }
  return value >> 232n === day ? value & MASK232 : 0n;
}

export async function bafTopWord(s, level, index) {
  const schema = await loadSchema('JACKPOTS');
  if (!schema.fields.bafTopLevels) return s.field('JACKPOTS', 'bafTop', level, index);
  const bank = BigInt(Math.floor(Number(level) / 10) & 3);
  const tags = BigInt(await s.field('JACKPOTS', 'bafTopLevels'));
  if (((tags >> (bank * 24n)) & MASK24) !== BigInt(level)) return 0n;
  return s.field('JACKPOTS', 'bafTop', bank, index);
}

export async function bafPlayerFor(s, level, player) {
  const schema = await loadSchema('JACKPOTS');
  if (!schema.fields.bafTopLevels) return s.field('JACKPOTS', 'bafPlayer', level, player);
  const [value, header] = await Promise.all([
    s.field('JACKPOTS', 'bafPlayer', player, Math.floor(Number(level) / 10) & 1),
    s.field('JACKPOTS', 'bafLevel', level),
  ]);
  return BigInt(value.bracket) === BigInt(level) && value.epoch === header.epoch
    ? value : { total: 0n, epoch: header.epoch, bracket: BigInt(level) };
}
